import re
from collections import Counter

JS_FILE = 'src/data/fortunePoems.js'

def analyze():
    with open(JS_FILE, 'r', encoding='utf-8') as f:
        content = f.read()

    # Regex to extract the Luck part from the title
    # Pattern: title: "第[digits]籤 [LuckString]"
    # Note: The JS file generated by our previous script uses json.dumps, so weird characters are escaped, 
    # but Chinese characters usually stay as is or \uXXXX.
    # Our previous script used ensure_ascii=False, so they should be readable Chinese.
    
    # Matches: title: "第1籤 大吉"
    matches = re.findall(r'title: "第\d+籤\s(.*?)"', content)

    if not matches:
        print("No poems found or format mismatch.")
        return

    total = len(matches)
    print(f"Total Poems Found: {total}")

    # Normalize
    normalized_luck = []
    for luck in matches:
        # Trim whitespace
        l = luck.strip()
        # Normalize '兇' to '凶'
        l = l.replace('兇', '凶')
        normalized_luck.append(l)

    counts = Counter(normalized_luck)
    
    print(f"\n{'Luck Type (運勢)':<10} | {'Count (數量)':<10} | {'Probability (機率)':<10}")
    print("-" * 40)
    
    # Sort by count desc
    for luck, count in counts.most_common():
        percentage = (count / total) * 100
        print(f"{luck:<12} | {count:<10} | {percentage:.1f}%")

if __name__ == "__main__":
    analyze()
